package org.apache.commons.lang;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_availableLocaleSet_TriageGen2Test {

    /**
     * Since cAvailableLocaleSet is a static field that caches the result,
     * we use reflection to reset it to null before tests to ensure 
     * we can test both the 'null' and 'not null' branches.
     */
    private void resetCache() throws Exception {
        Field field = LocaleUtils.class.getDeclaredField("cAvailableLocaleSet");
        field.setAccessible(true);
        field.set(null, null);
    }

    @Test
    public void testAvailableLocaleSet_FirstCall_InitializesCache() throws Exception {
        // Reset to ensure the 'if (set == null)' branch is taken
        resetCache();

        Set result = LocaleUtils.availableLocaleSet();

        assertNotNull("The returned set should not be null", result);
        assertFalse("The set should not be empty", result.isEmpty());

        // Verify that the returned set is indeed unmodifiable by attempting to modify it
        try {
            result.add(Locale.US);
            fail("Expected UnsupportedOperationException when trying to modify unmodifiable set");
        } catch (UnsupportedOperationException e) {
            // Success
        }
    }




}

