package org.apache.commons.lang;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_availableLocaleSet_TriageGen2Test {

    /**
     * Since cAvailableLocaleSet is a static field that caches the result,
     * we use reflection to reset it to null before tests to ensure 
     * we can test both the 'null' and 'not null' branches.
     */
    private void resetCache() throws Exception {
        Field field = LocaleUtils.class.getDeclaredField("cAvailableLocaleSet");
        field.setAccessible(true);
        field.set(null, null);
    }





    @Test
    public void testAvailableLocaleSet_ContentsMatchAvailableList() throws Exception {
        resetCache();

        Set result = LocaleUtils.availableLocaleSet();
        java.util.List<Locale> expectedList = LocaleUtils.availableLocaleList();

        assertEquals("The set should contain all elements from availableLocaleList", 
                     expectedList.size(), result.size());
        assertTrue("The set should contain all locales from the list", 
                   result.containsAll(expectedList));
    }
}
